#endif

#if defined(RTCI_FFI_DRIVER)
// A shared port (C: `rtci_mux`). Thread-safe; free it after the peer connections using it.
typedef struct rtci_mux rtci_mux;
#endif

// A peer connection of the sans-I/O layer (C: `rtci_pc`). Not thread-safe: calls on one handle
// must not overlap.
typedef struct rtci_pc rtci_pc;

